/**
 * @description
 */

cc.Class({
    extends: require("LMSlots_Slots_Base"),

    properties: {
        _wheel_script: null,
        _curFreeLevel: 0,
        _isFreeGame : false,
        _wheelWin:0,
    },

    Init() {
        this._super();

        // 解锁条
        let bonus_node = cc.find("collect_node/bonus_node", this.node);
        let deskInfo = cc.vv.gameData.getDeskInfo();
        bonus_node.on(cc.Node.EventType.TOUCH_END, () => {
            if (deskInfo.needBet > deskInfo.currmult && cc.vv.gameData.GetSlotState() === "idle") {
                this._bottomScript.SetBetIdx(deskInfo.needBet);
            }
        });

        let script = cc.find("lock", bonus_node).getComponent(sp.Skeleton);
        if (deskInfo.needBet <= deskInfo.currmult) {
            cc.find("lock", bonus_node).active = false;
            cc.vv.AudioManager.playEff("games/OdinsAnger/", "unlock", true);
            script.clearTracks();
            script.setToSetupPose();
            script.setAnimation(0, "animation1", false);
            script.setCompleteListener((track) => {
                let name = track.animation ? track.animation.name : "";
                if (name === "animation1") {
                    cc.find("lock", bonus_node).active = false;
                }
            });
        } else {
            cc.find("lock", bonus_node).active = true;
            cc.vv.AudioManager.playEff("games/OdinsAnger/", "lock", true);
            script.clearTracks();
            script.setToSetupPose();
            script.setAnimation(0, "animation2", false);
        }

        // 解锁条的转盘要不停转动
        let small_wheel = cc.find("collect_node/small_wheel/mask/wheel", this.node);
        cc.tween(small_wheel)
            .repeatForever(
                cc.tween()
                    .by(4, {angle: -360})
            )
            .start();

        this.ReconnectShowWheel(deskInfo.collectGame);
    },

    //点击旋转按钮调用
    StartMove: function () {
        if (this._gameInfo && this._gameInfo.nextCollectGame) {
            this.updateCollectProgress(this._gameInfo.nextCollectGame, false);
        }
        this._super();

        this.setWheelWin(0);
        Global.SlotsSoundMgr.playNormalBgm();
    },

    async ReconnectShow() {
        this._super();
    },

    async ReconnectShowWheel(collectGame){
        // 进度条当前进度
        if(collectGame && collectGame.state === 3){   // 免费游戏中
            cc.vv.gameData.GetBottomScript().ShowBtnsByState("moveing_1")
        }
        await this.updateCollectProgress(collectGame, false);
        cc.vv.gameData.GetBottomScript().ShowBtnsByState("idle")
    },

    async onMsgSpine(msg) {
        this._super(msg);

        // 随机游戏
        if (this._gameInfo.mammothGame && !this._isFreeGame) {  // 动画原因，在免费游戏中不显示随机游戏动画
            this.SetStopTime(3);

            this.triggerRandomGame();
        }
    },

    //检查进入免费
    CheckEnterFreeGame: function () {
        return cc.vv.gameData.GetTotalFree() > 0 && cc.vv.gameData.GetFreeTime() === cc.vv.gameData.GetTotalFree();
    },

    CheckExtraFreeGame() {
        return !!(this._gameInfo.freeResult && this._gameInfo.freeResult.freeInfo && this._gameInfo.freeResult.freeInfo.freeCnt > 0);
    },

    CheckExitFreeGame() {
        return cc.vv.gameData.GetTotalFree() > 0 && cc.vv.gameData.GetFreeTime() === 0;
    },

    //显示中奖路线
    //竞品中的显示线路是：先总，后单条循环。目前我们只显示总的
    async ShowWinTrace() {
        return new Promise(async (success) => {
            let allWinIdx = []

            //中奖位置
            for (let i = 0; i < this._gameInfo.zjLuXian.length; i++) {
                let item = this._gameInfo.zjLuXian[i]
                for (let idx = 0; idx < item.indexs.length; idx++) {
                    allWinIdx[item.indexs[idx]] = 1
                }
            }
            // if (this._gameInfo.scatterZJLuXian && this._gameInfo.scatterZJLuXian.indexs) {
            //     for (let i = 0; i < this._gameInfo.scatterZJLuXian.indexs.length; i++) {
            //         let val = this._gameInfo.scatterZJLuXian.indexs[i]
            //         allWinIdx[val] = 1
            //     }
            // }

            if (cc.vv.gameData.GetTotalFree() > 0 &&
                cc.vv.gameData.GetTotalFree() !== cc.vv.gameData.GetFreeTime()) {
                let hasWild = false;
                for (const key in allWinIdx) {
                    let symbol = this.GetSymbolByIdx(Number(key))
                    if (symbol) {
                        if (this._cfg.wildIds.indexOf(symbol.GetShowId()) !== -1) {
                            hasWild = true;
                            symbol.playWinAnimation();
                        }
                    }
                }
                if (hasWild) {
                    cc.vv.AudioManager.playEff("games/OdinsAnger/", "wild_multiplier", true);
                    await this.awaitTime(1.5);
                }
            }

            //总
            for (const key in allWinIdx) {
                let symbol = this.GetSymbolByIdx(Number(key))
                if (symbol) {
                    if (cc.vv.gameData.GetTotalFree() > 0 &&
                        cc.vv.gameData.GetTotalFree() !== cc.vv.gameData.GetFreeTime() &&
                        this._cfg.wildIds.indexOf(symbol.GetShowId()) !== -1) {

                    } else {
                        symbol.playWinAnimation()
                    }
                    symbol.ShowKuang()
                }
            }

            success();
        });
    },

    //重写：显示bonus中奖
    async OnSpinEnd() {
        if (this._gameInfo.freeCollect) {
            await this.triggerCollectInFree();
            await this.ShowWinTrace();
        } else {
            this.ShowWinTrace();
            if(this._gameInfo.wheelGame){   // 能触发转盘，等转盘转完，不能触发则不等
                await this.triggerCollect();
            } else {
                this.triggerCollect();
            }
        }

        let winCoin = cc.vv.gameData.GetGameWin();
        let totalWinCoin = cc.vv.gameData.GetGameWin();
        if(this._gameInfo.wheelGame){   // 转盘赢钱
            winCoin += this._wheelWin;
            totalWinCoin += this._wheelWin;
        }
        if (cc.vv.gameData.GetTotalFree() > 0 && cc.vv.gameData.GetTotalFree() !== cc.vv.gameData.GetFreeTime()) {
            // 免费中
            totalWinCoin = cc.vv.gameData.GetGameTotalFreeWin();
        }

        this.ShowBottomWin(winCoin, totalWinCoin, true, async () => {
            if (this.CheckEnterFreeGame()) {
                this.triggerFreeGame();
            } else if (this.CheckExtraFreeGame()) {
                this.triggerExtraFreeGame();
            } else {
                if (this.CheckExitFreeGame()) {
                    this.triggerExitFreeGame();
                } else {
                    if (cc.vv.gameData.GetTotalFree() > 0 && cc.vv.gameData.GetTotalFree() !== cc.vv.gameData.GetFreeTime()) {
                        // 免费中
                        let freeCollect = this._gameInfo.freeCollect;
                        let cfg = freeCollect.cfg;
                        for (let i = 0; i < cfg.length; i++) {
                            let num = cfg[i].total - freeCollect.num;
                            if (num <= 0) {
                                num = 0;
                                let node = cc.find("free_collect_node/node_" + (i + 1), this.node);
                                if (cc.find("collect", node).active) {
                                    let sz_qh_02 = cc.find("sz_qh_02", node);
                                    sz_qh_02.active = true;
                                    sz_qh_02.getComponent(sp.Skeleton).setToSetupPose();
                                    sz_qh_02.getComponent(sp.Skeleton).setAnimation(0, "animation", false);
                                    sz_qh_02.getComponent(sp.Skeleton).setCompleteListener(()=>{
                                        sz_qh_02.active = false;
                                    });
                                    cc.vv.AudioManager.playEff("games/OdinsAnger/", "golden_change", true);
                                    cc.find("collect", node).active = false;
                                    cc.find("full", node).active = true;
                                }
                            }
                        }
                    }
                    // await this.awaitTime(0.5);

                    this.CanDoNextRound();
                }
            }
        });
    },

    async triggerCollect() {
        let collectGame = this._gameInfo.collectGame;
        if (collectGame.state === 3) {
            this._bottomScript.ShowBtnsByState("unstoped");
        }
        let moveTime = 0.8;

        if (collectGame.state !== 0) {
            // 可以收集
            let haveCollect = false;
            let endPos = cc.find("collect_node/icon_bg/spine_7", this.node).convertToWorldSpaceAR(cc.v2(0, 0));
            endPos = this.node.parent.convertToNodeSpaceAR(endPos);

            for (let i = 0; i < this._gameInfo.resultCards.length; i++) {
                let card = this._gameInfo.resultCards[i];
                if (card === collectGame.card) {
                    haveCollect = true;
                    let node = cc.instantiate(cc.find("spine_collect_symbol_fly", this.node.parent));
                    node.active = true;
                    node.parent = this.node.parent;
                    let symbol = this.GetSymbolByIdx(i + 1);
                    let startPos = symbol.node.convertToWorldSpaceAR(cc.v2(0, 0));
                    startPos = this.node.parent.convertToNodeSpaceAR(startPos);
                    node.position = startPos;
                    let animation = "animation" + (card - 4);
                    let spine = node.getComponent(sp.Skeleton);
                    spine.setToSetupPose();
                    spine.setAnimation(0, animation, false);
                    let particle = cc.instantiate(cc.find("particle_tuowei", this.node.parent));
                    particle.parent = node;
                    particle.active = true;

                    cc.tween(node)
                        .delay(0.4)
                        .to(moveTime - 0.4, {position: endPos})
                        .removeSelf()
                        .start();
                }
            }

            if (haveCollect) {
                // 收集的地方特效
                // 粒子
                cc.vv.AudioManager.playEff("games/OdinsAnger/", "symbol_fly", true);
                await this.awaitTime(moveTime);
                cc.vv.AudioManager.playEff("games/OdinsAnger/", "symbol_receive", true);
                let particle = cc.instantiate(cc.find("particle_tuowei", this.node.parent));
                particle.parent = this.node.parent;
                particle.active = true;
                particle.position = endPos;
                cc.tween(particle)
                    .delay(0.5)
                    .removeSelf()
                    .start();

                let icon = cc.find("collect_node/icon_bg/spine_" + collectGame.card, this.node);
                let animation = "animation";
                if (collectGame.card === 6) {
                    animation = "animation1";
                }
                icon.getComponent(sp.Skeleton).setToSetupPose();
                icon.getComponent(sp.Skeleton).setAnimation(0, animation, false);

                let spine_collect = cc.find("collect_node/progress/node/spine_collect", this.node).getComponent(sp.Skeleton);
                spine_collect.node.active = true;
                spine_collect.node.parent.scaleX = collectGame.cnum / collectGame.total;
                spine_collect.setToSetupPose();
                spine_collect.setAnimation(0, "animation", false);
                spine_collect.setCompleteListener(() => {
                    spine_collect.node.active = false;
                });

                await this.updateCollectProgress(collectGame, true);
            } else {
                await this.updateCollectProgress(collectGame, false);
            }
        }
    },

    async triggerCollectInFree() {
        let freeCollect = this._gameInfo.freeCollect;
        if (freeCollect.level === 4) {
            return;
        }
        if (!freeCollect.idxs) {
            return;
        }
        let haveCollect = false;
        let endPos = cc.find("free_collect_node/node_" + (freeCollect.level + 1) + "/collect/num", this.node)
            .convertToWorldSpaceAR(cc.v2(0,0));
        let sz_qh_01 = cc.find("free_collect_node/node_" + (freeCollect.level + 1) + "/collect/sz_qh_01", this.node);
        if (this._curFreeLevel !== freeCollect.level) {
            // 满了
            endPos = cc.find("free_collect_node/node_" + freeCollect.level + "/collect/num", this.node)
                .convertToWorldSpaceAR(cc.v2(0,0));
            sz_qh_01 = cc.find("free_collect_node/node_" + freeCollect.level + "/collect/sz_qh_01", this.node);
        }
        this._curFreeLevel = freeCollect.level;
        endPos = this.node.parent.convertToNodeSpaceAR(endPos);

        for (let i = 0; i < freeCollect.idxs.length; i++) {
            let index = freeCollect.idxs[i];
            haveCollect = true;
            let node = cc.instantiate(cc.find("spine_collect_symbol_fly", this.node.parent));
            node.active = true;
            node.parent = this.node.parent;
            let symbol = this.GetSymbolByIdx(index);
            let startPos = symbol.node.convertToWorldSpaceAR(cc.v2(0, 0));
            startPos = this.node.parent.convertToNodeSpaceAR(startPos);
            node.position = startPos;
            let animation = "animation1";
            let spine = node.getComponent(sp.Skeleton);
            spine.setToSetupPose();
            spine.setAnimation(0, animation, false);

            cc.tween(node)
                .delay(0.4)
                .to(0.4, {position: endPos})
                .removeSelf()
                .start();

            let newNode = cc.instantiate(cc.find("spine_collect_symbol_fly", this.node.parent));
            newNode.active = true;
            newNode.parent = this.node.parent;
            newNode.position = startPos;
            let newSpine = newNode.getComponent(sp.Skeleton);
            newSpine.setToSetupPose();
            newSpine.setAnimation(0, "animation2_1", false);
            newSpine.setCompleteListener(()=>{
                symbol.ShowById(6);
                newNode.removeFromParent();
            });
        }

        if (haveCollect) {
            // 收集的地方特效
            cc.vv.AudioManager.playEff("games/OdinsAnger/", "golden_on_reel", true);
            await this.awaitTime(0.8);


            sz_qh_01.active = true;
            sz_qh_01.getComponent(sp.Skeleton).setToSetupPose();
            sz_qh_01.getComponent(sp.Skeleton).setAnimation(0, "animation", false);
            sz_qh_01.getComponent(sp.Skeleton).setCompleteListener(()=>{
                sz_qh_01.active = false;
            });

            let cfg = freeCollect.cfg;
            for (let i = 0; i < cfg.length; i++) {
                let num = cfg[i].total - freeCollect.num;
                if (num < 0) {
                    num = 0
                }
                cc.find("free_collect_node/node_" + (i + 1) + "/collect/num", this.node).getComponent(cc.Label).string = num;
            }
        }
    },

    async triggerFreeGame() {
        this._bottomScript.ShowBtnsByState("moveing_1");

        this._curFreeLevel = 0;

        for (let i = 0; i < this._gameInfo.resultCards.length; i++) {
            let card = this._gameInfo.resultCards[i];
            if (card === this._cfg.scatterId) {
                let symbol = this.GetSymbolByIdx(i + 1);
                symbol.playWinAnimation();
            }
        }

        cc.vv.AudioManager.playEff("games/OdinsAnger/", "fg_bell", true);
        // 触发免费游戏
        await this.awaitTime(2);

        await this.popFreeDialog(false);

        this.cutScenesElephant();

        await this.awaitTime(1.7);

        this.Backup();
        this.ShowGameview(true);

        await this.awaitTime(2);

        Global.SlotsSoundMgr.stopBgm();
        Global.SlotsSoundMgr.playBgm("free_bgm");
        this.CanDoNextRound();
    },

    async triggerExtraFreeGame() {
        this._bottomScript.ShowBtnsByState("moveing_1");

        for (let i = 0; i < this._gameInfo.resultCards.length; i++) {
            let card = this._gameInfo.resultCards[i];
            if (card === this._cfg.scatterId) {
                let symbol = this.GetSymbolByIdx(i + 1);
                symbol.playWinAnimation();
            }
        }

        cc.vv.AudioManager.playEff("games/OdinsAnger/", "fg_bell", true);

        await this.awaitTime(2);

        await this.popFreeDialog(true);

        this.CanDoNextRound();
    },

    async triggerExitFreeGame() {
        this._bottomScript.ShowBtnsByState("moveing_1");

        await this.awaitTime(1);

        await this.popFreeResultDialog();

        this.cutScenesElephant();

        await this.awaitTime(1.7);

        this.Resume();
        this.ShowGameview(false);

        this.ShowBottomWin(cc.vv.gameData.GetGameTotalFreeWin(), cc.vv.gameData.GetGameTotalFreeWin(), true, () => {
            Global.SlotsSoundMgr.stopBgm();
            Global.SlotsSoundMgr.playNormalBgm();
            this.CanDoNextRound();
        });
    },

    cutScenesElephant() {
        let character = cc.find("character", this.node.parent);
        if(character.active){
            character.active = false;
        }
        cc.vv.AudioManager.playEff("games/OdinsAnger/", "transition", true);
        let QP_01 = cc.find("QP_01", this.node.parent);
        QP_01.active = true;
        QP_01.getComponent(sp.Skeleton).setToSetupPose();
        QP_01.getComponent(sp.Skeleton).setAnimation(0, "skill", false);
        QP_01.getComponent(sp.Skeleton).setCompleteListener(() => {
            QP_01.active = false;
        })
    },

    //显示游戏界面：bFree true显示免费模式的界面，false 普通模式
    ShowGameview: function (bFree) {
        this._super(bFree);

        this._isFreeGame = bFree;

        cc.find("collect_node", this.node).active = !bFree;
        cc.find("free_collect_node", this.node).active = bFree;
        cc.find("character", this.node.parent).active = !bFree;

        if (bFree) {
            let freeCollect = (this._gameInfo && this._gameInfo.freeCollect) ?
                this._gameInfo.freeCollect : cc.vv.gameData.getDeskInfo().freeGameData.collect;
            let cfg = freeCollect.cfg;
            for (let i = 0; i < cfg.length; i++) {
                cc.find("free_collect_node/node_" + (i + 1) + "/collect/num", this.node).getComponent(cc.Label).string =
                    cfg[i].total - freeCollect.num;
            }

            for (let i = 1; i < 5; i++) {
                cc.find("free_collect_node/node_" + i + "/collect", this.node).active = i > freeCollect.level;
                cc.find("free_collect_node/node_" + i + "/full", this.node).active = i <= freeCollect.level;
            }
        }
    },

    shake() {
        let safe_node = this.node.parent;
        for (let child of safe_node.children) {
            if (child.name !== "LMSlots_Top" && child.name !== "LMSlots_Bottom" && child.name !== "character" && child.active) {
                let action = cc.shake(3, 15, 15);
                child.runAction(action);
            }
        }
    },

    triggerRandomGame() {
        cc.vv.AudioManager.playEff("games/OdinsAnger/", "stimulate", true);

        let character = cc.find("character", this.node.parent);
        character.getComponent(sp.Skeleton).setAnimation(0, "skill2", false);
        character.getComponent(sp.Skeleton).addAnimation(0, "idle", true);

        // let spine = cc.find("spine_randomgame", this.node);
        // spine.active = true;
        // spine.getComponent(sp.Skeleton).setToSetupPose();
        // spine.getComponent(sp.Skeleton).setAnimation(0, "animation", false);

        this.shake();
    },

    popFreeDialog(isExtra) {
        return new Promise(async (success) => {
            let free_dialog = cc.find("free_dialog", this.node.parent);
            free_dialog.active = true;

            let free_bg = cc.find("free_dialog_bg", free_dialog);
            free_bg.opacity = 0;
            free_bg.runAction(cc.fadeTo(0.2, 200));

            let dialog = cc.find("common_enter_node", free_dialog);
            if (isExtra) {
                dialog = cc.find("extra_node", free_dialog);
                // cc.vv.AudioManager.playEff("games/MammothGrandGems/", "retrigger_board_land", true);
            }

            dialog.active = true;
            dialog.scale = 0;
            Global.SlotsSoundMgr.stopBgm();
            cc.vv.AudioManager.playEff("games/OdinsAnger/", "popup_trigger", true);
            dialog.runAction(cc.scaleTo(0.5, 1).easing(cc.easeBackOut()));

            if (isExtra) {
                cc.find("times", dialog).getComponent(cc.Label).string = this._gameInfo.freeResult.freeInfo.freeCnt;

                await this.awaitTime(2);

                cc.vv.AudioManager.playEff("games/OdinsAnger/", "popup_out", true);

                dialog.runAction(cc.sequence(
                    cc.scaleTo(0.5, 0),
                    cc.callFunc(() => {
                        dialog.active = false;
                        free_dialog.active = false;

                        success();
                    })
                ));

                free_bg.runAction(cc.fadeOut(0.2));
            } else {
                let btn = cc.find("btn", dialog);
                cc.find("times", dialog).getComponent(cc.Label).string = cc.vv.gameData.GetTotalFree();
                await this.awaitTime(0.5);

                let closeFunc = function(){
                    btn.off(cc.Node.EventType.TOUCH_END);
                    cc.vv.AudioManager.playEff("games/OdinsAnger/", "popup_out", true);
                    dialog.runAction(cc.sequence(
                        cc.scaleTo(0.5, 0),
                        cc.callFunc(() => {
                            dialog.active = false;
                            free_dialog.active = false;

                            success();
                        })
                    ));

                    free_bg.runAction(cc.fadeOut(0.2));
                };
                cc.vv.gameData.checkAutoPlay(dialog, closeFunc);

                btn.off(cc.Node.EventType.TOUCH_END);
                btn.on(cc.Node.EventType.TOUCH_END, () => {
                    btn.stopAllActions();
                    cc.vv.AudioManager.playEff("games/OdinsAnger/", "free_dialog_collect_click", true);
                    closeFunc();
                });
            }
        });
    },

    popFreeResultDialog() {
        return new Promise(async (success) => {
            Global.SlotsSoundMgr.stopBgm();
            cc.vv.AudioManager.playEff("games/OdinsAnger/", "free_dialog_collect_show", true);

            let free_dialog = cc.find("free_dialog", this.node.parent);
            free_dialog.active = true;

            let free_bg = cc.find("free_dialog_bg", free_dialog);
            free_bg.opacity = 0;
            free_bg.runAction(cc.fadeTo(0.2, 200));

            let dialog = cc.find("result_node", free_dialog);

            dialog.active = true;
            dialog.scale = 0;

            dialog.runAction(cc.scaleTo(0.5, 1).easing(cc.easeBackOut()));

            Global.doRoallNumEff(cc.find("coin", dialog), 0, cc.vv.gameData.GetGameTotalFreeWin(), 3, null, null, 0, true);

            await this.awaitTime(0.5);
            let closeFunc = function(){
                cc.find("btn_collect", dialog).off("click");
                let delayT = 0;
                if(Global.FormatCommaNumToNum(cc.find("coin", dialog).getComponent(cc.Label).string) != cc.vv.gameData.GetGameTotalFreeWin()){
                    cc.find("coin", dialog).stopAllActions();
                    cc.find("coin", dialog).getComponent(cc.Label).string = Global.FormatNumToComma(cc.vv.gameData.GetGameTotalFreeWin());
                    delayT = 0.3;
                }

                cc.vv.AudioManager.playEff("games/OdinsAnger/", "popup_out", true);
                dialog.runAction(cc.sequence(
                    cc.delayTime(delayT),
                    cc.scaleTo(0.5, 0),
                    cc.callFunc(() => {
                        dialog.active = false;
                        free_dialog.active = false;

                        success();
                    })
                ));

                free_bg.runAction(cc.fadeOut(0.2));
            };

            cc.vv.gameData.checkAutoPlay(dialog, closeFunc);
            cc.find("btn_collect", dialog).off("click");
            cc.find("btn_collect", dialog).on("click", () => {
                dialog.stopAllActions();
                cc.vv.AudioManager.playEff("games/OdinsAnger/", "free_dialog_collect_click", true);
                closeFunc();
            });
        })
    },

    async updateCollectProgress(collectGame, isAdd) {
        cc.find("collect_node/counter", this.node).active = collectGame.state !== 2;
        cc.find("collect_node/spin_counter", this.node).active = collectGame.state !== 2;
        cc.find("collect_node/tips_failed", this.node).active = collectGame.state === 2;
        cc.find("collect_node/progress/spine_full", this.node).active = collectGame.state === 3;
        cc.find("collect_node/small_wheel/spine_full", this.node).active = collectGame.state === 3;

        let bar = cc.find("collect_node/progress/mask/bar", this.node);
        if (collectGame.state === 2) {
            // 失败了
            cc.vv.AudioManager.playEff("games/OdinsAnger/", "voice_mammoth", true);
            bar.position = cc.v2(0,0);
            // let progressCmp = cc.find("collect_node/progress", this.node).getComponent(cc.ProgressBar);
            // progressCmp.progress = 0;
        } else if (collectGame.state === 3) {
            cc.vv.AudioManager.playEff("games/OdinsAnger/", "collect_full", true);

            // 收集成功
            let counterCmp = cc.find("collect_node/counter/num", this.node).getComponent(cc.Label);
            counterCmp.string = "COLLECT  0";

            // 进度条
            if (isAdd) {
                cc.tween(bar)
                    .to(0.5, {position:cc.v2(bar.width*(collectGame.cnum / collectGame.total),0)})
                    .start()
            } else {
                bar.position = cc.v2(bar.width*(collectGame.cnum / collectGame.total),0)
            }
            // let progressCmp = cc.find("collect_node/progress", this.node).getComponent(cc.ProgressBar);
            // if (isAdd) {
            //     cc.tween(progressCmp)
            //         .to(0.5, {progress: collectGame.cnum / collectGame.total})
            //         .start();
            // } else {
            //     progressCmp.progress = collectGame.cnum / collectGame.total;
            // }

            // 剩余旋转次数
            let spinCounterCmp = cc.find("collect_node/spin_counter/num", this.node).getComponent(cc.Label);
            spinCounterCmp.string = "IN  " + (collectGame.spin - collectGame.snum) + "  SPIN";

            await this.awaitTime(2);

            cc.vv.AudioManager.playEff("games/OdinsAnger/", "fg_bell", true);

            await this.awaitTime(1);

            await this._wheel_script.startWheel(this._gameInfo ? this._gameInfo.wheelGame : cc.vv.gameData.getDeskInfo().wheelGame);
        } else {
            // 收集图标
            for (let i = 6; i < 11; i++) {
                cc.find("collect_node/icon_bg/spine_" + i, this.node).active = false;
            }
            cc.find("collect_node/icon_bg/spine_" + collectGame.card, this.node).active = true;

            // 当前需要收集数量
            let counterCmp = cc.find("collect_node/counter/num", this.node).getComponent(cc.Label);
            counterCmp.string = "COLLECT  " + (collectGame.total - collectGame.cnum);

            // 进度条
            if (isAdd) {
                cc.tween(bar)
                    .to(0.5, {position:cc.v2(bar.width*(collectGame.cnum / collectGame.total),0)})
                    .start()
            } else {
                bar.position = cc.v2(bar.width*(collectGame.cnum / collectGame.total),0)
            }
            // let progressCmp = cc.find("collect_node/progress", this.node).getComponent(cc.ProgressBar);
            // if (isAdd) {
            //     cc.tween(progressCmp)
            //         .to(0.5, {progress: collectGame.cnum / collectGame.total})
            //         .start();
            // } else {
            //     progressCmp.progress = collectGame.cnum / collectGame.total;
            // }

            // 剩余旋转次数
            let spinCounterCmp = cc.find("collect_node/spin_counter/num", this.node).getComponent(cc.Label);
            spinCounterCmp.string = "IN  " + (collectGame.spin - collectGame.snum) + "  SPIN";
        }
    },

    setWheelScript(script) {
        this._wheel_script = script;
    },

    setWheelWin(winCoin){
        this._wheelWin = winCoin;
    },

    awaitTime(time) {
        return new Promise((success, failed) => {
            this.scheduleOnce(() => {
                success()
            }, time);
        });
    },

    GetTimeScale(){
        return this._timeScaleVal || 1.5
    },
});