cc.Class({
    extends: require("LMSlots_Logic_Base"),

    properties: {
        _lockBonus: false,
    },

    // LIFE-CYCLE CALLBACKS:

    onLoad() {
        this._super();

        Global.registerEvent(cc.vv.gameData._EventId.SLOT_TOTALBET_UPDATED, this.onUpdateBet, this);

        let deskInfo = cc.vv.gameData.getDeskInfo();
        this._lockBonus = deskInfo.needBet > deskInfo.currmult;

        cc.vv.gameData.GetSlotsScript().setWheelScript(cc.find("safe_node/wheel", this.node).getComponent("OdinsAnger_Wheel"));

        // let msg_1 = cc.find("safe_node/msg_1", this.node);
        // msg_1.opacity = 255;
        // cc.tween(msg_1)
        //     .repeatForever(
        //         cc.tween()
        //             .delay(5)
        //             .to(1, {opacity: 0})
        //             .delay(5)
        //             .to(1, {opacity: 255})
        //     )
        //     .start();
        //
        // let msg_2 = cc.find("safe_node/msg_2", this.node);
        // msg_2.opacity = 0;
        // cc.tween(msg_2)
        //     .repeatForever(
        //         cc.tween()
        //             .delay(5)
        //             .to(1, {opacity: 255})
        //             .delay(5)
        //             .to(1, {opacity: 0})
        //     )
        //     .start();
    },

    onUpdateBet: function () {
        let deskInfo = cc.vv.gameData.getDeskInfo();
        let script = cc.find("safe_node/slots/collect_node/bonus_node/lock", this.node).getComponent(sp.Skeleton);
        if (deskInfo.needBet <= cc.vv.gameData.GetBetIdx() && this._lockBonus) {
            this._playLockTipsAnimation(false);
            cc.vv.AudioManager.playEff("games/OdinsAnger/", "unlock", true);
            this._lockBonus = false;
            script.clearTracks();
            script.setToSetupPose();
            script.setAnimation(0, "animation1", false);
            script.setCompleteListener((track) => {
                let name = track.animation ? track.animation.name : "";
                if (name === "animation1") {
                    cc.find("safe_node/slots/collect_node/bonus_node/lock", this.node).active = false;
                }
            });
        } else if (deskInfo.needBet > cc.vv.gameData.GetBetIdx() && !this._lockBonus) {
            this._playLockTipsAnimation(true);
            cc.vv.AudioManager.playEff("games/OdinsAnger/", "lock", true);
            this._lockBonus = true;
            cc.find("safe_node/slots/collect_node/bonus_node/lock", this.node).active = true;
            script.clearTracks();
            script.setToSetupPose();
            script.setAnimation(0, "animation2", false);
        }
    },

    _playLockTipsAnimation(isLock) {
        let lock_tips = cc.find("safe_node/slots/img_lock", this.node);
        let unlock_tips = cc.find("safe_node/slots/img_unlock", this.node);
        lock_tips.cleanup();
        unlock_tips.cleanup();
        lock_tips.active = isLock;
        unlock_tips.active = !isLock;
        lock_tips.y = -261;
        unlock_tips.y = -261;
        let node = isLock ? lock_tips : unlock_tips;
        cc.tween(node)
            .call(() => {
                cc.vv.AudioManager.playEff("games/OdinsAnger/", "text_in", true);
            })
            .by(0.3, {y: 91})
            .delay(1)
            .call(() => {
                cc.vv.AudioManager.playEff("games/OdinsAnger/", "text_out", true);
            })
            .by(0.3, {y: -91})
            .start();
    },
});