/**
 * @description
 */

cc.Class({
    extends: cc.Component,
    properties: {
        black_bg: cc.Node,
        wheel_node: cc.Node,
        wheel: cc.Node,
        spine_win: sp.Skeleton,
        spine_idle: sp.Skeleton,
        spine_click: sp.Skeleton,
        result_node: cc.Node,
        winCoin: cc.Label,
        btn_collect: cc.Button,

        _successCallback: null,
    },

    onLoad() {
        cc.vv.NetManager.registerMsg(MsgId.SLOT_SUBGAME_DATA, this.onRcvSubgameData, this);
    },

    async startWheel(wheelGame) {
        return new Promise((success)=>{
            cc.find("LMSlots_PrizePool_1", this.node.parent).getComponent("LMSlots_PrizePool_Base").PausePool([
                {prizeType: 1, pauseNum: wheelGame.poolList[1]},
                {prizeType: 2, pauseNum: wheelGame.poolList[2]},
                {prizeType: 3, pauseNum: wheelGame.poolList[3]},
            ]);

            this._successCallback = success;
            this.node.active = true;
            this.black_bg.opacity = 0;
            Global.SlotsSoundMgr.stopBgm();
            Global.SlotsSoundMgr.playBgm("bonus_bgm");
            cc.tween(this.black_bg)
                .to(0.5, {opacity: 200})
                .start();

            let cfg = wheelGame.cfg;
            for (let i = 0; i < cfg.length; i++) {
                let item = cfg[i];
                if (item.rtype === "MULT") {
                    let node = cc.find("index_" + (i + 1), this.wheel);
                    if (node) {
                        node.getComponent(cc.Label).string = Global.formatNumShort(item.num, 0);
                    }
                }
            }

            this.wheel_node.active = true;
            this.wheel_node.y = -cc.winSize.height;
            this.wheel.rotation = 0;
            this.spine_win.node.active = false;
            this.spine_idle.clearTracks();
            this.spine_idle.setToSetupPose();
            this.spine_idle.setAnimation(0, "animation1", true);
            this.spine_click.node.active = false;

            let self = this;
            cc.tween(this.wheel_node)
                .delay(0.2)
                .call(()=>{
                    cc.vv.AudioManager.playEff("games/OdinsAnger/", "wheel_out", true);
                })
                .by(0.3, {y: cc.winSize.height})
                .call(()=>{
                    let spinFunc = function(){
                        self.spine_idle.node.off(cc.Node.EventType.TOUCH_END);
                        let req = {c: MsgId.SLOT_SUBGAME_DATA};
                        req.gameid = cc.vv.gameData.getGameId();
                        req.data = {};
                        req.data.rtype = 1;
                        cc.vv.NetManager.send(req, true);
                    };

                    cc.vv.gameData.checkAutoPlay(self.spine_idle.node, spinFunc);

                    this.spine_idle.node.off(cc.Node.EventType.TOUCH_END);
                    this.spine_idle.node.on(cc.Node.EventType.TOUCH_END, ()=>{
                        self.spine_idle.node.stopAllActions();
                        cc.vv.AudioManager.playEff("games/OdinsAnger/", "wheel_click_spinbtn", true);
                        spinFunc();
                    })
                })
                .start();

            this.result_node.active = false;
        })

    },

    async onRcvSubgameData(msg) {
        this.spine_click.node.active = true;
        this.spine_click.setToSetupPose();
        this.spine_click.setAnimation(0, "animation", false);
        this.spine_click.setCompleteListener(()=>{
            this.spine_click.node.active = false;
        });

        cc.tween(this.spine_idle)
            .delay(0.5)
            .call(()=>{
                this.spine_idle.clearTracks();
                this.spine_idle.setToSetupPose();
                this.spine_idle.setAnimation(0, "animation2", true);
            })
            .start();

        await this._rotateWheel(msg.data.idx - 1);

        this.spine_win.node.active = true;
        this.spine_win.setToSetupPose();
        this.spine_win.setAnimation(0, "animation", true);
        cc.vv.AudioManager.playEff("games/OdinsAnger/", "wheel_celebration", true);

        await this.awaitTime(3);

        this.spine_win.active = false;

        Global.SlotsSoundMgr.stopBgm();
        cc.vv.AudioManager.playEff("games/OdinsAnger/", "free_dialog_collect_show", true);
        this.result_node.active = true;
        this.result_node.scale = 0;
        cc.tween(this.result_node)
            .to(0.4, {scale: 1}, {easing: "backOut"})
            .start();

        Global.doRoallNumEff(this.winCoin.node, 0, msg.data.winCoin, 3, null, null, 0, true);

        let self = this;
        let collectFunc = function(){
            return new Promise(async (succes)=>{
                self.btn_collect.node.off("click");
                cc.vv.AudioManager.playEff("games/OdinsAnger/", "popup_out", true);

                self.winCoin.node.stopAllActions();
                if(Global.FormatCommaNumToNum(self.winCoin.string) < msg.data.winCoin){
                    self.winCoin.string = Global.FormatNumToComma( msg.data.winCoin);
                    await self.awaitTime(0.2);
                }

                cc.tween(self.result_node)
                    .to(0.4, {scale: 0}, {easing: "backIn"})
                    .start();

                cc.tween(self.wheel_node)
                    .delay(0.2)
                    .by(0.4, {y: -cc.winSize.height})
                    .start();

                cc.tween(self.black_bg)
                    .delay(0.2)
                    .to(0.4, {opacity: 0})
                    .start();

                cc.tween(self.node)
                    .delay(0.3)
                    .call(()=>{
                        cc.vv.gameData.GetSlotsScript().updateCollectProgress(msg.data.nextCollectGame, false);
                    })
                    .delay(0.3)
                    .call(()=>{
                        // 钱跟slots赢的钱一起加
                        cc.vv.gameData.AddCoin(msg.data.winCoin);
                        cc.vv.gameData.GetSlotsScript().setWheelWin(msg.data.winCoin);
                        // cc.vv.gameData.GetSlotsScript().ShowBottomWin(msg.data.winCoin, msg.data.winCoin, true, ()=>{
                        if (self._successCallback) {
                            self._successCallback();
                            self._successCallback = null;
                            Global.SlotsSoundMgr.stopBgm();
                            Global.SlotsSoundMgr.playNormalBgm();
                            self.node.active = false;

                            cc.find("LMSlots_PrizePool_1", self.node.parent).getComponent("LMSlots_PrizePool_Base").ResumePausePool();
                        }
                        // })
                    })
                    .start();
            })
        };

        await cc.vv.gameData.checkAutoPlay(this.btn_collect.node, collectFunc);

        this.btn_collect.node.off("click");
        this.btn_collect.node.on("click", async ()=>{
            this.btn_collect.node.stopAllActions();
            await collectFunc()
        });
    },

    async _rotateWheel(endIndex) {
        return new Promise((success)=>{
            let angle = endIndex * 40 - 2160;
            cc.log(angle);
            cc.vv.AudioManager.playEff("games/OdinsAnger/", "wheel_spin", true);
            let action = cc.rotateBy(6, angle).easing(cc.easeSineInOut());
            this.wheel.runAction(cc.sequence(action, cc.callFunc(()=>{
                cc.vv.AudioManager.playEff("games/OdinsAnger/", "wheel_end", true);
                success();
            })));
        });
    },

    onDestroy() {
        cc.vv.NetManager.unregisterMsg(MsgId.SLOT_SUBGAME_DATA, this.onRcvSubgameData, false, this);
    },

    awaitTime(dt) {
        return new Promise((success, failed) => {
            this.scheduleOnce(() => {
                success()
            }, dt);
        });
    }
})